// Avoid modulo bias by generating a random number in a range that's a multiple of n
uint32_t limit = std::numeric_limits<uint32_t>::max() - (std::numeric_limits<uint32_t>::max() % n);
uint32_t result;
do {
    result = Next();
} while (result >= limit);
return result % n;

